**makeCounter(start)**

Write `makeCounter(start)`: return an object with `increment()` (adds 1, returns the new count) and `current()`. Each counter must keep its own private count. Don't change `check`.

```js
// Test driver: don't change.
function check(start) {
  const a = makeCounter(start);
  const b = makeCounter(100);
  return [a.increment(), a.increment(), b.increment(), a.current(), b.current()];
}

function makeCounter(start) {
  // TODO: keep the count in a variable the returned functions close over
  return { increment() {}, current() {} };
}
```

notes.back:
// Why: Each call to makeCounter creates a new `count`, and the returned methods close over
// that one. A variable outside the function would be shared by every counter.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Closures
// Test driver: don't change.
function check(start) {
  const a = makeCounter(start);
  const b = makeCounter(100);
  return [a.increment(), a.increment(), b.increment(), a.current(), b.current()];
}

function makeCounter(start) {
  let count = start;
  return {
    increment() {
      count += 1;
      return count;
    },
    current() {
      return count;
    },
  };
}

