**once(fn)**

Write `once(fn)`: return a function that calls `fn` the first time only and returns that first result on every later call — even when the result is `undefined`. Don't change `check`.

```js
// Test driver: don't change.
function check(values) {
  let calls = 0;
  const double = once((x) => {
    calls++;
    return x * 2;
  });
  const results = values.map((v) => double(v));
  let logs = 0;
  const log = once(() => {
    logs++;
  });
  log();
  log();
  return { results, calls, logs };
}

function once(fn) {
  // TODO
  return fn;
}
```

notes.back:
// Why: Track "already called" in its own flag. Using the result itself as the flag breaks
// for a function that returns undefined: it gets called again.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Closures
// Test driver: don't change.
function check(values) {
  let calls = 0;
  const double = once((x) => {
    calls++;
    return x * 2;
  });
  const results = values.map((v) => double(v));
  let logs = 0;
  const log = once(() => {
    logs++;
  });
  log();
  log();
  return { results, calls, logs };
}

function once(fn) {
  let done = false;
  let result;
  return (...args) => {
    if (!done) {
      done = true;
      result = fn(...args);
    }
    return result;
  };
}

